using Azure;using Azure.Identity;using Azure.Storage.Blobs;using EnterpriseDocumentIntelligence.BuildingBlocks.Infrastructure;var builder=WebApplication.CreateBuilder(args);builder.Services.AddControllers();builder.Services.AddEndpointsApiExplorer();builder.Services.AddSwaggerGen();builder.Services.AddHealthChecks();builder.Services.AddBuildingBlocks(builder.Configuration,"DocumentService");builder.Services.AddSingleton(sp=>{var c=sp.GetRequiredService<IConfiguration>();var uri=c["Storage:BlobServiceUri"]??throw new InvalidOperationException("Storage:BlobServiceUri missing");var key=c["Storage:ConnectionString"];return string.IsNullOrWhiteSpace(key)?new BlobServiceClient(new Uri(uri),new DefaultAzureCredential()):new BlobServiceClient(key);});var app=builder.Build();app.UseSwagger();app.UseSwaggerUI();app.UseHttpsRedirection();app.UseBuildingBlocks();app.MapControllers();app.MapHealthChecks("/health/live");app.MapHealthChecks("/health/ready");app.Run();